From dfe5783f1c3e0e7526bbab36b1afcf889766db0b Mon Sep 17 00:00:00 2001
From: Serge Vakulenko <serge.vakulenko@gmail.com>
Date: Wed, 22 Jul 2015 19:08:58 -0700
Subject: [PATCH] Bootloader mode: fix a few issues introduced by change
 a1d322d (block size, devcfg access and others).


diff --git a/target.c b/target.c
index dfc0af7..d827095 100644
--- a/target.c
+++ b/target.c
@@ -44,7 +44,7 @@ family_t family_mz  = { "mz",
  */
 static const
 family_t family_bl  = { "bootloader",
-                        80, 0,      2048, 0,         0,           1052, 0      };
+                        80, 0,      1024, 0,         0,           0,    0      };

 /*
  * Table of PIC32 chip variants.
@@ -391,24 +391,16 @@ unsigned target_flash_bytes (target_t *t)

 unsigned target_boot_bytes (target_t *t)
 {
-    if (! t->family)
-        return t->boot_bytes;
     return t->family->boot_kbytes * 1024;
 }

 unsigned target_devcfg_offset (target_t *t)
 {
-    if (! t->family)
-        return 0;
     return t->family->devcfg_offset;
 }

 unsigned target_block_size (target_t *t)
 {
-    if (! t->family) {
-        /* Use 1024k block for bootloader. */
-        return 1024;
-    }
     return t->family->bytes_per_row;
 }

@@ -417,7 +409,7 @@ unsigned target_block_size (target_t *t)
  */
 void target_use_executive (target_t *t)
 {
-    if (t->adapter->load_executive != 0 && t->family)
+    if (t->adapter->load_executive != 0 && t->family->pe_nwords != 0)
         t->adapter->load_executive (t->adapter, t->family->pe_code,
             t->family->pe_nwords, t->family->pe_version);
 }
@@ -427,7 +419,7 @@ void target_use_executive (target_t *t)
  */
 void target_print_devcfg (target_t *t)
 {
-    if (! t->family)
+    if (! t->family->devcfg_offset)
         return;

     unsigned devcfg_addr = 0x1fc00000 + target_devcfg_offset (t);
@@ -573,7 +565,7 @@ void target_program_block (target_t *t, unsigned addr,
 void target_program_devcfg (target_t *t, unsigned devcfg0,
         unsigned devcfg1, unsigned devcfg2, unsigned devcfg3)
 {
-    if (! t->family)
+    if (! t->family->devcfg_offset)
         return;

     unsigned addr = 0x1fc00000 + t->family->devcfg_offset;
-- 
2.25.1

Based on the commit message, the root cause and the patch provided below, you need to:

1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
Bootloader mode: fix a few issues introduced by change
 a1d322d (block size, devcfg access and others).

Here is the root cause:
The bug was caused by incorrect values in the `family_bl` structure, specifically the `bytes_per_row` and `devcfg_offset`, which led to improper handling of bootloader configurations. Additionally, the removal of null checks for `t->family` in various functions indicated an assumption that `t->family` would always be valid, which could lead to unexpected behavior if that assumption was violated.

Here is the patch:
 static const
 family_t family_bl  = { "bootloader",
-                        80, 0,      2048, 0,         0,           1052, 0      };
+                        80, 0,      1024, 0,         0,           0,    0      };

 /*

 unsigned target_boot_bytes (target_t *t)
 {
-    if (! t->family)
-        return t->boot_bytes;
     return t->family->boot_kbytes * 1024;
 }

 unsigned target_devcfg_offset (target_t *t)
 {
-    if (! t->family)
-        return 0;
     return t->family->devcfg_offset;
 }

 unsigned target_block_size (target_t *t)
 {
-    if (! t->family) {
-        /* Use 1024k block for bootloader. */
-        return 1024;
-    }
     return t->family->bytes_per_row;
 }

  */
 void target_use_executive (target_t *t)
 {
-    if (t->adapter->load_executive != 0 && t->family)
+    if (t->adapter->load_executive != 0 && t->family->pe_nwords != 0)
         t->adapter->load_executive (t->adapter, t->family->pe_code,
             t->family->pe_nwords, t->family->pe_version);
 }

  */
 void target_print_devcfg (target_t *t)
 {
-    if (! t->family)
+    if (! t->family->devcfg_offset)
         return;

     unsigned devcfg_addr = 0x1fc00000 + target_devcfg_offset (t);
     unsigned devcfg3 = t->adapter->read_word (t->adapter, devcfg_addr);
     unsigned devcfg2 = t->adapter->read_word (t->adapter, devcfg_addr + 4);
     unsigned devcfg1 = t->adapter->read_word (t->adapter, devcfg_addr + 8);
     unsigned devcfg0 = t->adapter->read_word (t->adapter, devcfg_addr + 12);

     if (devcfg3 == 0xffffffff && devcfg2 == 0xffffffff &&
         devcfg1 == 0xffffffff && devcfg0 == 0x7fffffff)
         return;
     if (devcfg3 == 0 && devcfg2 == 0 && devcfg1 == 0 && devcfg0 == 0)
         return;

     printf (_("Configuration:\n"));
     t->family->print_devcfg (devcfg0, devcfg1, devcfg2, devcfg3);
 }

  */
 void target_program_devcfg (target_t *t, unsigned devcfg0,
         unsigned devcfg1, unsigned devcfg2, unsigned devcfg3)
 {
-    if (! t->family)
+    if (! t->family->devcfg_offset)
         return;

     unsigned addr = 0x1fc00000 + t->family->devcfg_offset;

     //fprintf (stderr, "%s: devcfg0-3 = %08x %08x %08x %08x\n", __func__, devcfg0, devcfg1, devcfg2, devcfg3);
     if (t->family->pe_version >= 0x0500) {
         /* Since pic32mz, the programming executive */
         t->adapter->program_quad_word (t->adapter, addr, devcfg3,
             devcfg2, devcfg1, devcfg0);
         return;
     }

     t->adapter->program_word (t->adapter, addr, devcfg3);
     t->adapter->program_word (t->adapter, addr + 4, devcfg2);
     t->adapter->program_word (t->adapter, addr + 8, devcfg1);
     t->adapter->program_word (t->adapter, addr + 12, devcfg0);
 }
-- 


